# R/algorithm.R
# Manual file - NOT generated by orchestrate.R
# GDAL's own algorithm registry, which is what the `gdal` command line runs.

# "raster reproject", c("raster", "reproject") and "raster  reproject" are the
# same path. GDAL's own naming is the vocabulary, so there is nothing to learn
# twice.
algorithm_path <- function(path) {
  if (is.null(path)) {
    return(character(0))
  }
  if (!is.character(path)) {
    stop("An algorithm is named by a string, such as \"raster reproject\"",
         call. = FALSE)
  }
  # unlist() on an empty split gives NULL, and the C side wants a character
  # vector either way.
  parts <- as.character(unlist(strsplit(path, "[[:space:]]+"), use.names = FALSE))
  parts[nzchar(parts)]
}

#' Whether this GDAL has algorithms to run
#'
#' The algorithm registry arrived in GDAL 3.11. Everything in [gdal_run()],
#' [gdal_algorithms()] and [gdal_algorithm_info()] depends on it, and raises an
#' error naming the release when it is not there.
#'
#' Having the API is not the same as having the algorithms. A GDAL can be built
#' with them turned off, and before GDAL 3.12 each algorithm registered itself
#' as a side effect of being loaded, which a static link leaves out, so a
#' statically linked GDAL 3.11 answers from an empty registry. This checks
#' both, so TRUE means there is something to run.
#'
#' @return TRUE or FALSE.
#' @export
#' @examples
#' gdal_has_algorithms()
gdal_has_algorithms <- function() {
  GDAL7_algorithms_available() &&
    length(GDAL7_algorithm_names(character(0))) > 0L
}

#' List GDAL's algorithms
#'
#' The registry is a tree: `gdal_algorithms()` gives the top level, and passing
#' one of those names gives what is under it. These are the same names the
#' `gdal` command line uses.
#'
#' @param path An algorithm's name, as a string such as `"raster"` or
#'   `"raster reproject"`, or a character vector of its parts. NULL, the
#'   default, lists the top level.
#' @return A character vector of names, empty when the algorithm has nothing
#'   under it.
#' @export
#' @examples
#' if (gdal_has_algorithms()) {
#'   gdal_algorithms()
#'   gdal_algorithms("raster")
#' }
gdal_algorithms <- function(path = NULL) {
  GDAL7_algorithm_names(algorithm_path(path))
}

#' Describe one of GDAL's algorithms
#'
#' What the algorithm does, what it is called, and every argument it takes with
#' its type and whether it is required. This is the reference for what to put in
#' the `args` of [gdal_run()], read out of GDAL itself rather than copied into
#' this package.
#'
#' @param path The algorithm, as for [gdal_algorithms()].
#' @return A list: `name`, `description`, `long_description`, `url`,
#'   `sub_algorithms`, and `arguments`, a data frame with one row per argument.
#'   Its `choices` column is a list, holding the allowed values of the arguments
#'   that have a fixed set and nothing for the rest.
#' @export
#' @examples
#' if (gdal_has_algorithms()) {
#'   info <- gdal_algorithm_info("raster reproject")
#'   info$description
#'   head(info$arguments[c("name", "type", "required")])
#' }
gdal_algorithm_info <- function(path) {
  info <- GDAL7_algorithm_info(algorithm_path(path))
  arguments <- info$arguments
  choices <- arguments$choices
  arguments$choices <- NULL
  out <- as.data.frame(arguments, stringsAsFactors = FALSE)
  out$choices <- choices
  info$arguments <- out
  info
}

#' Run one of GDAL's algorithms
#'
#' Arguments are given by name, exactly as [gdal_algorithm_info()] reports them,
#' and are converted according to the type GDAL declares for each. A dataset
#' argument takes either a GDALDataset, which is handed over as it stands, or a
#' string for GDAL to open.
#'
#' What comes back depends on where the algorithm was told to put its result.
#' Given an output format of `"MEM"` and an empty output name it works in
#' memory and hands back the GDALDataset, with nothing touching disk. Given a
#' file name it writes the file, closes it properly, and hands back the path.
#'
#' A long algorithm draws a progress bar and can be interrupted with Ctrl-C.
#' The interrupt is passed to GDAL, which stops at the next step it checks, so
#' it takes effect at the algorithm's own granularity rather than instantly.
#'
#' @param path The algorithm, as for [gdal_algorithms()].
#' @param args A named list of arguments.
#' @param progress Whether to draw a progress bar. Interactive sessions do by
#'   default.
#' @return Invisibly: the output GDALDataset for an in-memory result, the path
#'   for one written to a file, or NULL for an algorithm that produces no
#'   dataset at all. A file has been written and closed by the time this
#'   returns, so it can be opened straight away.
#' @export
#' @examples
#' if (gdal_has_algorithms()) {
#'   ds <- gdal_open(system.file("extdata/test.tif", package = "GDAL7"))
#'
#'   # Reprojected into memory: no file is written. The bounding box is given
#'   # because the fixture covers the whole globe, which Web Mercator does not.
#'   out <- gdal_run("raster reproject", list(
#'     input = ds,
#'     output = "",
#'     "output-format" = "MEM",
#'     "dst-crs" = "EPSG:3857",
#'     bbox = c(-180, -85, 180, 85),
#'     "bbox-crs" = "EPSG:4326"
#'   ), progress = FALSE)
#'
#'   out@projection
#'   gdal_close(out)
#'   gdal_close(ds)
#' }
gdal_run <- function(path, args = list(), progress = interactive()) {
  if (!is.list(args)) {
    stop("`args` must be a named list", call. = FALSE)
  }
  result <- GDAL7_algorithm_run(algorithm_path(path), unwrap_datasets(args),
                                isTRUE(progress))
  if (is.null(result)) {
    return(invisible(NULL))
  }
  if (is.character(result)) {
    return(invisible(result))
  }
  invisible(GDALDataset(.ptr = result))
}

# GDAL is given the pointer a GDALDataset holds, not the S7 object around it,
# so a dataset already open in R is used as it stands rather than reopened.
# A list of them is unwrapped one deep, which is what a dataset list argument
# takes.
unwrap_datasets <- function(args) {
  unwrap_one <- function(value) {
    if (inherits(value, "GDAL7::GDALDataset")) {
      return(value@.ptr)
    }
    if (is.list(value)) {
      return(lapply(value, unwrap_one))
    }
    value
  }
  lapply(args, unwrap_one)
}
